parameters.functionCode:
// Validate booking payload fields
const item = items[0].json;
if (!item.guest_name || !item.property || !item.trip || !item.trip.check_in || !item.trip.check_out) {
  throw new Error('Invalid booking payload: Missing required fields');
}

return [{
  json: {
    booking_id: item.booking_id || `BK-${Date.now()}`,
    guest_name: item.guest_name,
    property: item.property,
    trip: item.trip,
    preferences: item.preferences || ['beach', 'food', 'nightlife'],
    telegram_chat_id: item.telegram_chat_id || '123456789'
  }
}];

